// Public mail providers: the address is redacted, but the provider domain is not.
const PUBLIC_MAIL_DOMAINS = ['gmail.com','googlemail.com','outlook.com','hotmail.com','live.com','yahoo.com','icloud.com','me.com','proton.me','protonmail.com','libero.it','virgilio.it','tiscali.it','alice.it','tim.it','pec.it'];

// Optional: extra literal strings to always redact (account names, company names, hostnames...).
const EXTRA_SENSITIVE_TERMS = [];

const item = $input.first();
// Keep the historical field identifier only as an input-data compatibility alias.
const rawNoteChoice = item.json?.['Regenerate sticky notes and node layout'] ?? item.json?.['Rigenera note e disposizione dei nodi'];
if(Array.isArray(rawNoteChoice)&&rawNoteChoice.length!==1)throw Error('Select exactly one option for sticky notes: Yes or No.');
const noteChoice = String((Array.isArray(rawNoteChoice)?rawNoteChoice[0]:rawNoteChoice)??'').trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
// Older submissions without the new required field keep the existing regeneration behavior.
const regenerateStickyNotes = !noteChoice || /^(si|yes|true)(?:$|\s|[—–-])/.test(noteChoice) ? true : /^(no|false)(?:$|\s|[—–-])/.test(noteChoice) ? false : null;
if(regenerateStickyNotes===null)throw Error('Invalid sticky-note choice: select Yes or No in the form.');
const keys = Object.keys(item.binary || {});
if (!keys.length) throw new Error('Upload a workflow JSON file');
const buf = await this.helpers.getBinaryDataBuffer(0, keys[0]);
if(buf.length > 1500000) throw Error('JSON exceeds 1.5 MB');
let wf;
try { wf = JSON.parse(buf.toString('utf8')); } catch (e) { throw new Error('Invalid JSON: ' + e.message); }
if (!wf || typeof wf !== 'object' || !Array.isArray(wf.nodes)) throw new Error('Missing nodes array');

const allowed = new Set(ALLOWED_EMAILS.map(e => e.toLowerCase()));
const publicDomains = new Set(PUBLIC_MAIL_DOMAINS);
const registrable = d => {
  const l = String(d).toLowerCase().split('.');
  if (l.length <= 2) return l.join('.');
  const sld = l[l.length - 2];
  return (l[l.length - 1].length === 2 && ['co','com','org','net','gov','ac','edu'].includes(sld)) ? l.slice(-3).join('.') : l.slice(-2).join('.');
};
const allowedRegistrable = new Set(ALLOWED_EMAILS.map(e => registrable(e.split('@')[1])));

const PH = t => '[REDACTED_' + t + ']';
const findings = [];
const known = new Map();        // value -> {type, substr}
const ownedDomains = new Set();
let keptAllowed = 0;

const mask = v => { v = String(v); return v.length <= 6 ? '*'.repeat(v.length) : v.slice(0, 2) + '…' + v.slice(-2) + ' (' + v.length + ' chars)'; };
const rec = (type, where, val) => findings.push({ type, where, preview: val === undefined ? '' : mask(val) });
const learn = (val, type, isName) => {
  if (typeof val !== 'string') return;
  const v = val.trim();
  if (v.length < 6 || v.startsWith('[REDACTED')) return;
  const substr = isName ? (v.length >= 8 && /[_\-\d@.]/.test(v)) : true;
  known.set(v, { type, substr });
};

const isLit = v => typeof v === 'string' && v.trim() !== '' && !v.startsWith('=');
const looksOpaque = v => /^[A-Za-z0-9_-]{20,}$/.test(v) && /\d/.test(v) && /[A-Za-z]/.test(v);
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const SENS_KEY = /(pass(?:word|phrase)?|passwd|secret|token|authorization|api[-_ ]?key|apikey|private[-_ ]?key|client[-_ ]?secret|cookie|bearer|signature|signing)/i;
const SENS_KEY_EXCLUDE = /(url|uri|type|name|field|label|expir|limit|count|usage|mode|path)$/i;
const ID_KEY = /^(workflow|project|credential|instance|user|owner|account|chat|channel|team|tenant|webhook|folder|database|spreadsheet|document|calendar|base|table|list|board|page|sheet|drive|org|organization|workspace)_?id$/i;

const PATTERNS = [
  { type: 'PRIVATE_KEY', re: /-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g },
  { type: 'JWT', re: /\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\b/g },
  { type: 'API_KEY', re: /\bsk-(?:ant-|proj-|svcacct-|admin-)?[A-Za-z0-9_-]{16,}\b/g },
  { type: 'API_KEY', re: /\b(?:AKIA|ASIA)[A-Z0-9]{16}\b/g },
  { type: 'API_KEY', re: /\b(?:ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9]{30,}\b/g },
  { type: 'API_KEY', re: /\bgithub_pat_[A-Za-z0-9_]{40,}\b/g },
  { type: 'API_KEY', re: /\bxox[abprs]-[A-Za-z0-9-]{10,}\b/g },
  { type: 'API_KEY', re: /\bAIza[0-9A-Za-z_-]{30,}\b/g },
  { type: 'API_KEY', re: /\b[sr]k_(?:live|test)_[A-Za-z0-9]{16,}\b/g },
  { type: 'API_KEY', re: /\bwhsec_[A-Za-z0-9]{16,}\b/g },
  { type: 'API_KEY', re: /\b(?:secret|ntn)_[A-Za-z0-9]{30,}\b/g },
  { type: 'API_KEY', re: /\bpat[A-Za-z0-9]{14}\.[a-f0-9]{64}\b/g },
  { type: 'API_KEY', re: /\bSG\.[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{16,}\b/g },
  { type: 'API_KEY', re: /\bkey-[0-9a-f]{32}\b/g },
  { type: 'API_KEY', re: /\b\d{8,10}:[A-Za-z0-9_-]{35}\b/g },
  { type: 'WEBHOOK_URL', re: /https:\/\/hooks\.slack\.com\/services\/[A-Za-z0-9\/]+/g },
  { type: 'WEBHOOK_URL', re: /https:\/\/(?:discord|discordapp)\.com\/api\/webhooks\/[0-9]+\/[A-Za-z0-9_-]+/g },
  { type: 'BEARER_TOKEN', re: /\bBearer\s+[A-Za-z0-9._~+\/=-]{12,}/gi, rep: () => 'Bearer ' + PH('BEARER_TOKEN') },
  { type: 'URL_CREDENTIALS', re: /\b([a-z][a-z0-9+.-]*:\/\/)[^\s\/:@"']+:[^\s\/@"']+@/gi, rep: (m, p) => p + PH('URL_CREDENTIALS') + '@' },
  { type: 'INTERNAL_URL', re: /\bhttps?:\/\/(?:localhost|127\.\d+\.\d+\.\d+|10\.\d+\.\d+\.\d+|192\.168\.\d+\.\d+|172\.(?:1[6-9]|2\d|3[01])\.\d+\.\d+|[a-z0-9.-]+\.(?:local|internal|lan))(?::\d+)?[^\s"'`)<>]*/gi },
  { type: 'WEBHOOK_PATH', re: /(\/(?:webhook|webhook-test|webhook-waiting|form|form-test|mcp)\/)[A-Za-z0-9_-]{8,}/g, rep: (m, p) => p + PH('WEBHOOK_PATH') },
  { type: 'SECRET_VALUE', re: /\b(password|passwd|pwd|secret|token|api[_-]?key|apikey|client_secret|access[_-]?key)\b(["']?\s*[:=]\s*)(["'])([^"'\n]{4,})\3/gi, rep: (m, k, sep, q, v) => (v.startsWith('[REDACTED') || v.startsWith('{{') || v.startsWith('=')) ? m : k + sep + q + PH('SECRET_VALUE') + q }
];
// the generic key/value rule must record the *value*, not the whole match
const EMAIL_RE = /[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}/g;

const scanString = (s, where) => {
  let out = s;
  for (const p of PATTERNS) {
    out = out.replace(p.re, (...m) => {
      const r = p.rep ? p.rep(...m) : PH(p.type);
      if (r === m[0]) return r;
      rec(p.type, where, p.type === 'SECRET_VALUE' ? m[4] : m[0]);
      return r;
    });
  }
  out = out.replace(EMAIL_RE, m => {
    if (allowed.has(m.toLowerCase())) { keptAllowed++; return m; }
    rec('EMAIL', where, m);
    const d = m.split('@')[1].toLowerCase();
    if (!publicDomains.has(d) && !allowedRegistrable.has(registrable(d))) ownedDomains.add(registrable(d));
    return PH('EMAIL');
  });
  return out;
};

const walkRl = (v, where, key) => {
  const lit = isLit(v.value);
  const redactIt = lit && (v.mode === 'url' || (key && ID_KEY.test(key)) || looksOpaque(v.value));
  const out = {};
  for (const [k, x] of Object.entries(v)) {
    if (redactIt && k === 'value') { rec('RESOURCE_ID', where + '.value', x); learn(x, 'RESOURCE_ID'); out[k] = PH('RESOURCE_ID'); }
    else if (redactIt && k === 'cachedResultName' && typeof x === 'string') { rec('RESOURCE_NAME', where + '.' + k, x); learn(x, 'RESOURCE_NAME', true); out[k] = PH('RESOURCE_NAME'); }
    else if (redactIt && k === 'cachedResultUrl' && typeof x === 'string') { rec('RESOURCE_URL', where + '.' + k, x); learn(x, 'RESOURCE_URL'); out[k] = PH('RESOURCE_URL'); }
    else out[k] = walk(x, where + '.' + k, k);
  }
  return out;
};

function walk(v, where, key) {
  if (typeof v === 'string') {
    if (key === 'path' && isLit(v) && (UUID_RE.test(v) || looksOpaque(v))) { rec('WEBHOOK_PATH', where, v); learn(v, 'WEBHOOK_PATH'); return PH('WEBHOOK_PATH'); }
    if (key && ID_KEY.test(key) && isLit(v) && !v.startsWith('[REDACTED')) { rec('RESOURCE_ID', where, v); learn(v, 'RESOURCE_ID'); return PH('RESOURCE_ID'); }
    if (key && SENS_KEY.test(key) && !SENS_KEY_EXCLUDE.test(key) && isLit(v) && !/^\d+$|^(true|false)$/i.test(v.trim()) && !v.startsWith('[REDACTED')) { rec('SECRET_VALUE', where, v); learn(v, 'SECRET_VALUE'); return PH('SECRET_VALUE'); }
    return scanString(v, where);
  }
  if (Array.isArray(v)) return v.map((x, i) => walk(x, where + '[' + i + ']', key));
  if (v && typeof v === 'object') {
    if (v.__rl === true) return walkRl(v, where, key);
    const nameSens = typeof v.name === 'string' && SENS_KEY.test(v.name) && !SENS_KEY_EXCLUDE.test(v.name) && isLit(v.value);
    const out = {};
    for (const [k, x] of Object.entries(v)) {
      if (nameSens && k === 'value') { rec('SECRET_VALUE', where + '.value (' + v.name + ')', x); learn(x, 'SECRET_VALUE'); out[k] = PH('SECRET_VALUE'); continue; }
      out[k] = walk(x, where + '.' + k, k);
    }
    return out;
  }
  return v;
}

for (const t of EXTRA_SENSITIVE_TERMS) learn(t, 'CUSTOM_TERM');

// ---------- 1) workflow-level identifiers ----------
const clean = JSON.parse(JSON.stringify(wf));
const originalStickyNoteCount = clean.nodes.filter(n => n.type === 'n8n-nodes-base.stickyNote').length;
const removedStickyNotes = regenerateStickyNotes ? originalStickyNoteCount : 0;
if(regenerateStickyNotes)clean.nodes = clean.nodes.filter(n => n.type !== 'n8n-nodes-base.stickyNote');
const dropTop = [['id','WORKFLOW_ID'],['versionId','VERSION_ID'],['activeVersionId','VERSION_ID'],['projectId','PROJECT_ID']];
for (const [k, t] of dropTop) {
  if (clean[k] !== undefined) { rec(t, 'workflow.' + k, typeof clean[k] === 'string' ? clean[k] : undefined); learn(clean[k], t); delete clean[k]; }
}
for (const k of ['shared','homeProject','sharedWithProjects','usedCredentials','ownedBy','createdBy','updatedBy']) {
  if (clean[k] !== undefined) { rec('OWNERSHIP_INFO', 'workflow.' + k); delete clean[k]; }
}
if (clean.meta && typeof clean.meta === 'object' && clean.meta.instanceId) {
  rec('INSTANCE_ID', 'workflow.meta.instanceId', clean.meta.instanceId); learn(clean.meta.instanceId, 'INSTANCE_ID'); delete clean.meta.instanceId;
}
if (clean.settings && typeof clean.settings === 'object') {
  for (const k of ['errorWorkflow','callerIds']) {
    if (clean.settings[k] !== undefined) { rec('WORKFLOW_ID', 'workflow.settings.' + k, typeof clean.settings[k] === 'string' ? clean.settings[k] : undefined); learn(clean.settings[k], 'WORKFLOW_ID'); delete clean.settings[k]; }
  }
}
if (Array.isArray(clean.tags)) {
  clean.tags = clean.tags.map(t => { if (t && typeof t === 'object' && t.id !== undefined) { rec('TAG_ID', 'workflow.tags', String(t.id)); learn(String(t.id), 'TAG_ID'); const { id, ...rest } = t; return rest; } return t; });
}
if (clean.pinData && typeof clean.pinData === 'object' && Object.keys(clean.pinData).length) { rec('PIN_DATA', 'workflow.pinData (' + Object.keys(clean.pinData).length + ' nodes)'); clean.pinData = {}; }
if (clean.staticData) { rec('STATIC_DATA', 'workflow.staticData'); delete clean.staticData; }

// ---------- 2) node-level: credentials, webhook IDs/paths, parameters ----------
clean.nodes = clean.nodes.map(n => {
  const label = 'node "' + (n.name || n.id) + '"';
  if (n.webhookId) { rec('WEBHOOK_ID', label + '.webhookId', n.webhookId); learn(n.webhookId, 'WEBHOOK_ID'); delete n.webhookId; }
  if (n.credentials && typeof n.credentials === 'object') {
    for (const [type, c] of Object.entries(n.credentials)) {
      if (c && c.id) { rec('CREDENTIAL_ID', label + '.credentials.' + type, c.id); learn(String(c.id), 'CREDENTIAL_ID'); }
      if (c && c.name) { rec('CREDENTIAL_NAME', label + '.credentials.' + type, c.name); learn(String(c.name), 'CREDENTIAL_NAME', true); }
      n.credentials[type] = { id: '', name: PH('CREDENTIAL_NAME') };
    }
  }
  if (n.parameters && typeof n.parameters === 'object') {
    if (isLit(n.parameters.path) && (UUID_RE.test(n.parameters.path) || looksOpaque(n.parameters.path))) {
      rec('WEBHOOK_PATH', label + '.parameters.path', n.parameters.path); learn(n.parameters.path, 'WEBHOOK_PATH'); n.parameters.path = PH('WEBHOOK_PATH');
    }
    n.parameters = walk(n.parameters, label + ' › parameters', 'parameters');
  }
  if (typeof n.notes === 'string') n.notes = scanString(n.notes, label + '.notes');
  return n;
});
if (typeof clean.name === 'string') clean.name = scanString(clean.name, 'workflow.name');
if (clean.settings) clean.settings = walk(clean.settings, 'workflow.settings', 'settings');
if (clean.meta) clean.meta = walk(clean.meta, 'workflow.meta', 'meta');

// ---------- 3) global sweep: every other occurrence of anything found above ----------
let text = JSON.stringify(clean, null, 2);
const esc = s => JSON.stringify(s).slice(1, -1);
const reEsc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const sorted = [...known.entries()].sort((a, b) => b[0].length - a[0].length);
for (const [val, { type, substr }] of sorted) {
  const needle = substr ? esc(val) : '"' + esc(val) + '"';
  const repl = substr ? PH(type) : '"' + PH(type) + '"';
  const parts = text.split(needle);
  if (parts.length > 1) { for (let i = 1; i < parts.length; i++) rec(type, 'other occurrences (global sweep)', val); text = parts.join(repl); }
}
for (const d of ownedDomains) {
  const re = new RegExp('(?:[a-z0-9-]+\\.)*' + reEsc(d) + '\\b', 'gi');
  text = text.replace(re, m => { rec('DOMAIN', 'global sweep', m); return PH('DOMAIN'); });
}
text = text.replace(EMAIL_RE, m => { if (allowed.has(m.toLowerCase())) return m; rec('EMAIL', 'global sweep', m); return PH('EMAIL'); });
let cleanWorkflow;
try { cleanWorkflow = JSON.parse(text); } catch (e) { throw new Error('Sanitized workflow is not valid JSON: ' + e.message); }

// ---------- 4) verification ----------
const residual = [...known.keys()].filter(v => text.includes(esc(v))).length;
const residualEmails = (text.match(EMAIL_RE) || []).filter(m => !allowed.has(m.toLowerCase())).length;

if(residual !== 0 || residualEmails !== 0) throw Error('Sanitization residual verification failed; email blocked.');

// ---------- 5) report (values are masked, never printed in clear) ----------
const byType = {};
for (const f of findings) byType[f.type] = (byType[f.type] || 0) + 1;
const cell = s => String(s).replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
const sourceFilename = item.binary[keys[0]].fileName || 'workflow.json';
const reportMarkdown = [
  '# Workflow sanitization report', '',
  '- Source file: ' + sourceFilename,
  '- Total redactions: ' + findings.length,
  '- Previous sticky notes removed: ' + removedStickyNotes,
  '- Sticky-note mode: ' + (regenerateStickyNotes ? 'regenerate notes and layout' : 'preserve sanitized notes and original layout'),
  '- Kept (not secrets): ' + ALLOWED_EMAILS.join(', ') + (keptAllowed ? ' (' + keptAllowed + ' occurrence(s))' : ''),
  '- Verification: ' + (residual === 0 && residualEmails === 0 ? 'passed, no known secret left in the cleaned file' : 'WARNING, ' + residual + ' value(s) and ' + residualEmails + ' email(s) still present'),
  '', '## By type', '',
  ...(Object.keys(byType).length ? Object.entries(byType).sort().map(([t, c]) => '- ' + t + ': ' + c) : ['- No secrets or identifiers found']),
  '', '## Details (values masked)', '',
  '| Type | Location | Preview |', '| --- | --- | --- |',
  ...findings.map(f => '| ' + cell(f.type) + ' | ' + cell(f.where) + ' | ' + cell(f.preview) + ' |'),
  ''
].join('\n');

const slug = String(cleanWorkflow.name || 'workflow').normalize('NFKD').replace(/[^A-Za-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'workflow';
return [{ json: { cleanWorkflow, regenerateStickyNotes, originalStickyNoteCount, removedStickyNotes, cleanFileName: slug + '_sanitized.json', reportMarkdown, report: { total: findings.length, byType, verificationPassed: residual === 0 && residualEmails === 0 }, sourceFilename } }];

const src = $input.first().json;
if(src.report?.verificationPassed!==true || src.stickyNotesReady!==true || src.layoutVerified!==true) throw Error('Incomplete sanitization, sticky notes or layout; email blocked.');
const file = async(text,name,mime) => this.helpers.prepareBinaryData(Buffer.from(text,'utf8'),name,mime);
const binary = {
  workflow_clean: await file(JSON.stringify(src.cleanWorkflow,null,2), src.cleanFileName, 'application/json'),
  redaction_report: await file(src.reportMarkdown, 'redaction-report.md', 'text/markdown'),
  sticky_notes: await file(src.stickyNotesMarkdown, 'sticky-notes.md', 'text/markdown'),
  layout_report: await file(JSON.stringify(src.layout,null,2), 'workflow-layout.json', 'application/json')
};
return [{json:{sanitizedWorkflow:true,secretsFound:src.report.total>0,redactionCount:src.report.total,verificationPassed:true,cleanFileName:src.cleanFileName,stickyNotesReady:true,layoutVerified:true,stickyNoteCount:src.stickyNoteCount,layout:src.layout},binary}];

const wf=$('Analyze uploaded JSON').first().json.workflow;
const services={},hosts=new Set(),triggers=[],types=new Set();
for(const n of wf.nodes){
  types.add(n.type);
  for(const c of n.credentialTypes||[]){(services[c]??={credentialType:c,usedBy:[]}).usedBy.push(n.name)}
  for(const m of JSON.stringify(n.parameters||{}).matchAll(/https?:\/\/([a-z0-9.-]+\.[a-z]{2,})/gi))hosts.add(m[1].toLowerCase());
  if(/trigger|webhook/i.test(n.type))triggers.push({name:n.name,type:n.type});
}
return [{json:{detected:{credentialTypes:Object.values(services),externalHosts:[...hosts].slice(0,30),triggers,nodeTypes:[...types],nodeCount:wf.nodeCount}}}];

function readAiJson(response, requiredKeys) {
  const finish = response.finish_reason ?? response.choices?.[0]?.finish_reason ?? response.message?.finish_reason;
  if (['length','max_tokens','content_filter'].includes(finish) || response.status === 'incomplete') throw Error('AI response incomplete (' + (finish || response.status) + '); no partial document will be published.');
  if (response.message?.refusal || response.choices?.[0]?.message?.refusal) throw Error('AI declined the documentation request.');
  let raw = response.message?.content ?? response.output?.[0]?.content ?? response.choices?.[0]?.message?.content ?? response.text;
  if (raw === undefined && requiredKeys.every(k => Object.hasOwn(response,k))) raw = response;
  if (Array.isArray(raw)) raw = raw.map(part => typeof part === 'string' ? part : part.text ?? '').join('');
  const details = {valid: true, recovered: false, recovery: null};
  let value;
  if (raw && typeof raw === 'object') value = raw;
  else if (typeof raw === 'string' && raw.trim()) {
    const text = raw.replace(/^\uFEFF/, '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
    try {value = JSON.parse(text);}
    catch (originalError) {
      // Recover only a complete root object followed solely by surplus closing delimiters.
      // Never evaluate model text, invent missing values or accept a second JSON document.
      const stack = []; let quoted = false, escaped = false, end = -1;
      if (text[0] === '{') for (let i = 0; i < text.length; i++) {
        const c = text[i];
        if (quoted) {if (escaped) escaped=false; else if (c==='\\') escaped=true; else if (c==='"') quoted=false; continue;}
        if (c==='"') {quoted=true; continue;}
        if (c==='{' || c==='[') stack.push(c);
        else if (c==='}' || c===']') {
          if (stack.pop() !== (c==='}' ? '{' : '[')) break;
          if (!stack.length) {end=i+1; break;}
        }
      }
      const suffix = end > 0 ? text.slice(end) : '';
      if (end < 0 || !suffix.trim() || !/^[\s\]}]+$/.test(suffix)) throw Error('Invalid AI JSON: ' + originalError.message + '. Response retained in the AI node; retry only that branch.');
      try {value = JSON.parse(text.slice(0,end));} catch {throw Error('AI JSON is malformed inside the document; cannot safely recover it.');}
      details.recovered=true; details.recovery='removed_surplus_closing_delimiters';
    }
  } else throw Error('Missing AI JSON content.');
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw Error('AI response must be a JSON object.');
  const missing=requiredKeys.filter(k=>!Object.hasOwn(value,k));
  if (missing.length) throw Error('AI response missing required fields: ' + missing.join(', '));
  return {value, details};
}

const aiParsed=readAiJson($input.first().json,["home_markdown","subpages"]);
let d=aiParsed.value;
const clean=s=>String(s??'').trim();
if(!d||typeof d!=='object')throw Error('Invalid documentation structure');
if(clean(d.home_markdown).length<45)throw Error('Detailed documentation introduction missing');
if(!Array.isArray(d.subpages)||d.subpages.length<2||d.subpages.length>6)throw Error('Invalid guide plan: expected 2-6 top-level pages');
const titles=new Set();let total=0;
const check=(s,min)=>{
  if(!s||!clean(s.title)||clean(s.markdown).length<min)throw Error('Guide empty or insufficient: '+(s?.title||'unnamed'));
  const key=clean(s.title).toLowerCase();if(titles.has(key))throw Error('Duplicate guide: '+s.title);titles.add(key);
  if(!/^#{2,3}\s+/m.test(s.markdown))throw Error('Guide missing headings: '+s.title);
  if(/^\s*\|.*\|\s*$/m.test(s.markdown)||/^```/m.test(s.markdown))throw Error('Unsupported Markdown table/code fence in: '+s.title);
  total++;
};
for(const s of d.subpages){
  check(s,700);
  if(s.children!==undefined&&!Array.isArray(s.children))throw Error('Invalid children in: '+s.title);
  if((s.children||[]).length>8)throw Error('Too many child guides in: '+s.title);
  for(const c of s.children||[]){if(Array.isArray(c.children)&&c.children.length)throw Error('Guides can be nested one level only: '+c.title);check(c,500)}
}
if(total>14)throw Error('Too many guides: '+total);
